  "tokenized_directions": [
    {
      "step": 1,
      "text": "Put {{ing_01|15 parts honey}} into a bronze vessel."
    },
    {
      "step": 2,
      "text": "Add {{ing_02|2 sextarii of wine}} to cook the {{ing_01|honey}}."
    },
    {
      "step": 3,
      "text": "Heat with a slow fire and dry wood, stirring with a rod while it cooks."
    },
    {
      "step": 4,
      "text": "If it begins to boil over, check it with a spray of {{ing_02|wine}}; when the fire is removed, it returns to itself."
    },
    {
      "step": 5,
      "text": "When it has cooled, light it again. This will be done a second and third time."
    },
    {
      "step": 6,
      "text": "Then finally remove it from the fire, and the next day, skim it."
    },
    {
      "step": 7,
      "text": "Grind {{ing_03|4 unciae of pepper}}, {{ing_04|3 scrupuli of mastic}}, {{ing_05|1 dragma each of bay leaf}} and {{ing_06|saffron}}."
    },
    {
      "step": 8,
      "text": "Take {{ing_07|5 roasted date pits}} and {{ing_08|5 dates}} softened with {{ing_02|wine}}, and with a prior pouring of {{ing_02|wine}} in its own manner and quantity, grind them so that a smooth grinding is obtained."
    },
    {
      "step": 9,
      "text": "When all these are prepared, add {{ing_09|18 sextarii of mild wine}}."
    },
    {
      "step": 10,
      "text": "Finally, add 2000 coals."
    }
